  /**
   * Initialize the SDK with Aadhaar validation
   * @param {string} aadhaar - The expected Aadhaar number to validate against
   * @param {boolean} isNewUser - Whether this is a new user registration
   * @param {Object} userData - User data for createUser (required if isNewUser is true)
   * @param {string} userData.name - User's full name
   * @param {string} userData.email - User's email address
   * @param {string} userData.phone - User's phone number
   * @param {Object} userData.additionalData - Any additional user data
   */
  async init(aadhaar, isNewUser = false, userData = null) {
    // Validate Aadhaar format
    if (!aadhaar || aadhaar.length !== 12 || !/^\d{12}$/.test(aadhaar)) {
      throw new Error("Invalid Aadhaar format. Must be a 12-digit number.");
    }

    if (isNewUser) {
      if (!userData) {
        throw new Error("userData is required for new user registration");
      }

      // Show OTP flow with Aadhaar validation for new users
      await this._showOtpFlow(aadhaar, userData, true);
      return;
    }

    // Existing user flow - validate Aadhaar input
    await this._showAadhaarValidationModal(aadhaar);
  }

