  async importWalletsFromFile(onComplete, currentAadhaar) {
    return new Promise((resolve, reject) => {
      const input = document.createElement("input");
      input.type = "file";
      input.accept = ".json";
      input.style.display = "none";

      let completed = false;

      input.addEventListener("change", async () => {
        const file = input.files[0];
        if (!file) {
          if (!completed) {
            completed = true;
            reject(new Error("No file selected"));
          }
          return;
        }

        try {
          const text = await file.text();
          const json = JSON.parse(text);
          
          if (typeof json !== "object" || Array.isArray(json)) {
            throw new Error("Invalid wallet file format");
          }

          // Calculate expected hash from Aadhaar
          const trimmedAadhaar = currentAadhaar.trim();
          const expectedHash = this.web3.utils.keccak256(trimmedAadhaar);
          
          console.log("🔍 Looking for wallet with hash:", expectedHash);
          console.log("🔍 Available hashes in file:", Object.keys(json));
          
          // Check if the expected hash exists in the file
          if (!json[expectedHash]) {
            throw new Error(`❌ No wallet found for Aadhaar ${trimmedAadhaar} in this file.\n\nThe uploaded file contains ${Object.keys(json).length} wallet(s) but none match your Aadhaar number.\n\nExpected hash: ${expectedHash}\nAvailable hashes: ${Object.keys(json).join(', ')}`);
          }
          
          // Try to decrypt the specific wallet entry
          console.log("✅ Found wallet entry, attempting to decrypt...");
          try {
            const encryptedPrivateKey = json[expectedHash];
            const decryptedPrivateKey = await this._decryptWithPin(encryptedPrivateKey);
            
            // Store the wallet in localStorage
            const wallets = store.get();
            wallets[expectedHash] = encryptedPrivateKey;
            store.set(wallets, false);
            console.log("💾 Wallet saved to localStorage with hash:", expectedHash);
            console.log("💾 Updated localStorage now contains:", Object.keys(store.get()));
            
            // Apply the account
            this._applyAccount(decryptedPrivateKey);
            
            console.log("✅ Wallet imported successfully!");
            if (onComplete) onComplete();
            completed = true;
            resolve();
            
          } catch (decryptError) {
            throw new Error(`❌ Failed to decrypt wallet: ${decryptError.message}\n\nThis is likely due to an incorrect PIN.`);
          }
        } catch (err) {
          console.error("Failed to import wallet file:", err.message);
          alert("❌ Failed to import wallet: " + err.message);
          completed = true;
          reject(err);
        }
      });

      // Handle case where user cancels file dialog - use a longer timeout
      const cancelTimeout = setTimeout(() => {
        if (!completed) {
          completed = true;
          reject(new Error("File upload cancelled"));
        }
      }, 120000); // 120 seconds timeout instead of focus detection

      // Clear timeout if change event fires
      input.addEventListener("change", () => {
        clearTimeout(cancelTimeout);
      }, { once: true });

      document.body.appendChild(input);
      input.click();
      document.body.removeChild(input);
    });
  }

