  // ── Low-level on-chain calls ─────────────────────────────────────────
  loadArtifact(name) {
    const artifact = abis[name];
    if (!artifact) throw new Error(`Missing ABI: ${name}`);
    return artifact;
  }

  async _send(contract, method, args = []) {
    const art = this.loadArtifact(contract + ".json");
    const ctr = new this.web3.eth.Contract(art.abi, art.deployedAddress);
    const data = ctr.methods[method](...args).encodeABI();

    // 0) fetch chain parameters
    const [chainId, gasPrice] = await Promise.all([
      this.web3.eth.getChainId(),
      this.web3.eth.getGasPrice(),
    ]);

    // 1) estimate gas (fallback to 500k)
    let gas;
    try {
      gas = await this.web3.eth.estimateGas({ to: ctr.options.address, data });
    } catch {
      console.warn("⚠️ Gas estimate failed, using 500k");
      gas = 500000;
    }

    // 2) build the full tx object
    const tx = {
      from: this.account.address,
      to: ctr.options.address,
      data,
      gas,
      gasPrice, // for pre-London / legacy chains
      chainId, // ties your signature to your Geth network
    };

    // 3) sign it
    const signed = await this.account.signTransaction(tx);

    // 4) send it
    try {
      return await this.web3.eth.sendSignedTransaction(signed.rawTransaction);
    } catch (err) {
      // if it reverted on-chain, try to decode the reason
      const receipt = err.receipt;
      if (receipt && receipt.status === false) {
        const reason = await this._decodeRevertReason({
          to: tx.to,
          from: tx.from,
          data: tx.data,
          blockNumber: receipt.blockNumber,
        });
        console.error(`❌ Transaction reverted: ${reason}`);
        throw new Error(`Transaction reverted: ${reason}`);
      }
      console.error("🚨 Transaction failed:", err.message || err);
      throw err;
    }
  }

  /**
   * @param {{to:string,from:string,data:string,blockNumber:number}} callTx
   */
  async _decodeRevertReason(callTx) {
    try {
      // replay the call one block earlier
      await this.web3.eth.call(
        { to: callTx.to, data: callTx.data, from: callTx.from, gas: 3000000 },
        callTx.blockNumber - 1
      );
      return "Unknown revert";
    } catch (callErr) {
      // Geth returns data under callErr.data or callErr.data[txHash]
      let errorData = callErr.data;
      if (errorData != null && typeof errorData === "object") {
        errorData = errorData[Object.keys(errorData)[0]];
      }
      if (typeof errorData === "string" && errorData.startsWith("0x08c379a0")) {
        // strip selector (4 bytes => 8 hex chars + "0x")
        const payload = "0x" + errorData.slice(10);
        return this.web3.eth.abi.decodeParameter("string", payload);
      }
      return "Cannot decode revert reason";
    }
  }

  async _call(contract, method, args = []) {
    const art = this.loadArtifact(contract + ".json");
    const ctr = new this.web3.eth.Contract(art.abi, art.deployedAddress);
    return ctr.methods[method](...args).call();
  }

