  /**
   * Grant `roleName` to `addr`, *and* for every fileID that this role
   * already has in KeyRegistry, decrypt the SDK’s copy of the AES key
   * and re‐encrypt it for the newly‐added address.
   *
   * @param {string} roleName – human‐readable role, e.g. "LOAN_OFFICER_ROLE"
   * @param {string} addr     – address to grant
   */
  async grantRole(roleName, addr) {
    // 1) do the on‐chain grant
    const tx = await this._send("RBACManager", "grantRoleByName", [
      roleName,
      addr,
    ]);

    // 2) compute the role hash
    const roleHash = this.web3.utils.keccak256(roleName);
    console.log(roleHash, "   roleHash");
    // 3) ask KeyRegistry which fileIDs this role already can decrypt
    const fileIds = await this.getFileIdsForRole(roleHash);

    console.log(fileIds, "   fileIds-----------------  grantRoleByName");

    // 4) for each file, grab *your* encrypted key, decrypt it, re‐encrypt for the new addr
    for (const fileId of fileIds) {
      try {
        // a) pull down the SDK’s copy of their encrypted AES key
        const sdkEncKey = await this.getEncryptedKey(fileId, this.address);
        if (!sdkEncKey) continue;

        // b) decrypt to raw AES buffer
        const aesBuf = this.decryptAESKey(sdkEncKey);

        // c) look up the new user’s on‐chain public key
        const userPub = await this.getUserPublicKeyByAddress(addr);
        if (!userPub?.startsWith("0x04") || userPub.length !== 132) {
          console.warn(
            `Skipping propagation for ${addr}; invalid pubkey:`,
            userPub
          );
          continue;
        }

        // d) encrypt the AES key for them
        const reEnc = this.encryptAESKeyForUser(aesBuf, userPub);

        // e) store it on‐chain
        await this.storeEncryptedKey(fileId, addr, reEnc);
      } catch (e) {
        console.warn(
          `Failed to propagate file ${fileId} to ${addr}:`,
          e.message
        );
      }
    }

    return tx;
  }
