  async assignFunctionRolesFor(roleName, fnSig) {
    const roleHash = this.web3.utils.keccak256(roleName);
    const selector = this.web3.utils.keccak256(fnSig).slice(0, 10);
    const assigned = await this._call("RBACManager", "getRolesForFunction", [
      selector,
    ]);
    if (!assigned.includes(roleHash)) {
      await this._send("RBACManager", "assignFunctionRole", [
        roleName,
        selector,
      ]);
      }
    
    // ── 2) Fetch all CIDs of this type from FileRegistry ──────────────
    // returns [ cids, aadhaarHashes, metadatas ]
    let result;
    if (fnSig == "getUser(bytes32)") 
      result = await this.getAllFilesByType("User");
    else if (fnSig == "getLoanByLoanId(bytes32)")
      result = await this.getAllFilesByType("Loan");
    
    if (fnSig == "getUser(bytes32)" || fnSig == "getLoanByLoanId(bytes32)") {
      const fileIds = result.map((obj) => this.hashCID(obj.cid));
      console.log(fileIds, "   fileIds----------- assignFunctionRolesFor");
      for (const fileId of fileIds) {
        await this._send("KeyRegistry", "grantFileRole", [fileId, roleHash]);
      }

      // ── 4) Propagate your AES keys to each current role member ─────────
      const members = await this._call("RBACManager", "getRoleMembers", [
        roleHash,
      ]);
      for (const fileId of fileIds) {
        // pull down *your* encrypted AES key
        const sdkEncKey = await this.getEncryptedKey(fileId, this.address);
        if (!sdkEncKey) continue;
        const aesBuf = this.decryptAESKey(sdkEncKey);

        for (const member of members) {
          const pub = await this.getUserPublicKeyByAddress(member);
          if (!pub?.startsWith("0x04") || pub.length !== 132) continue;
          const reEnc = this.encryptAESKeyForUser(aesBuf, pub);
          await this.storeEncryptedKey(fileId, member, reEnc);
        }
      }

      console.log(
        `✅ "${roleName}" can now call ${fnSig} functions, granted ${fileIds.length} files`
      );
    }
  }

