  /**
   * Uploads a buffer to IPFS, registers it in the FileRegistry,
   * and returns its CID and derived fileId.
   *
   * @param {Uint8Array|Buffer} buf        – The file data to upload.
   * @param {string} aadhaarHash           – The owner’s Aadhaar hash.
   * @param {string} fileType              – Must be either "User" or "Loan".
   * @param {string} metadata              – Arbitrary metadata to store.
   * @returns {Promise<{ cid: string, fileId: string }>}
   * @throws {Error} If fileType is invalid.
   */
  async uploadFile(buf, aadhaarHash, fileType, metadata) {
    if (!this.account) {
      throw new Error("Wallet not initialized – call init(aadhaar) first");
    }
    // validate fileType
    if (fileType !== "User" && fileType !== "Loan") {
      throw new Error(
        `Invalid fileType "${fileType}". Must be "User" or "Loan".`
      );
    }

    const aesKey = crypto.randomBytes(32);
    const encrypted = await this.encryptContent(buf, aesKey.toString("hex"));

    // upload to IPFS
    const { cid } = await this.uploadToIPFS(encrypted);
    const fileId = this.hashCID(cid);
    console.log(cid);

    let roleHashes = [];
    if (fileType === "User") {
      const selector = this.web3.utils
        .keccak256("getUser(bytes32)")
        .slice(0, 10);
      roleHashes = await this._call("RBACManager", "getRolesForFunction", [
        selector,
      ]);
      console.log(roleHashes, "   roleHashes");
    } else {
      const selector = this.web3.utils
        .keccak256("getLoanByLoanId(bytes32)")
        .slice(0, 10);
      roleHashes = await this._call("RBACManager", "getRolesForFunction", [
        selector,
      ]);
    }

    for (let roleHash of roleHashes) {
      await this._send("KeyRegistry", "grantFileRole", [fileId, roleHash]);
    }

    // register in FileRegistry
    await this.registerFileOnRegistry(aadhaarHash, cid, fileType, metadata);
    await this.grantFileAccessToValidCallers(
      fileId,
      aesKey,
      aadhaarHash,
      fileType
    );
    console.log("✅ Granted file access to user");

    return { cid, fileId };
  }

  /**
   * readFile
   *
   * Given an IPFS CID, derives the on-chain fileId, fetches the encrypted
   * AES key for the current user, pulls the cipher-text from IPFS,
   * decrypts it, and returns the original Buffer.
   *
   * @param {string} cid            - IPFS CID where the encrypted blob lives
   * @param {string} [userAddr]     - optional override of which address to pull the key for (defaults to the SDK’s own address)
   * @returns {Promise<Buffer>}     - the decrypted file contents
   */
  async readFile(cid, userAddr = this.address) {
    if (!this.account) {
      throw new Error("Wallet not initialized – call init(aadhaar) first");
    }
    // 1) derive the fileId from the CID
    const fileId = this.hashCID(cid);

    // 2) grab the encrypted AES key for this user + fileId
    const encKeyB64 = await this.getEncryptedKey(fileId, userAddr);
    if (!encKeyB64) {
      throw new Error(
        `No encrypted AES key found for fileId=${fileId} and user=${userAddr}`
      );
    }

    // 3) decrypt the AES key using our SDK private key
    const aesKeyBuf = this.decryptAESKey(encKeyB64);

    // 4) fetch the encrypted content from IPFS
    const encryptedContent = await this.getFromIPFS(cid);

    // 5) decrypt the content and return it
    const aesKeyHex = aesKeyBuf.toString("hex");
    return this.decryptContent(encryptedContent, aesKeyHex);
  }

