  // ── Crypto & IPFS Helpers ─────────────────────────────────────────
  async uploadToIPFS(buf) {
    console.log(typeof(buf), "   buf type in uploadToIPFS");
    if (!(buf instanceof Buffer || buf instanceof Uint8Array)) {
      throw new Error("uploadToIPFS requires a Buffer or Uint8Array");
    }
    if (!this.ipfs) {
      throw new Error("IPFS client not initialized");
    }
    const result = await this.ipfs.add(buf);
    return { cid: result.path };
  }

  async getFromIPFS(cidStr) {
    const chunks = [];
    for await (const chunk of this.ipfs.cat(cidStr)) {
      chunks.push(chunk);
    }
    return Buffer.concat(chunks);
  }

  encryptAESKeyForUser(aesBuf, userPubHex) {
    const pubKey = Buffer.from(userPubHex.replace(/^0x/, ""), "hex");
    return ecies.encrypt(pubKey, Buffer.from(aesBuf)).toString("base64");
  }

  decryptAESKey(encB64) {
    return ecies.decrypt(
      Buffer.from(this.privateKey.replace(/^0x/, ""), "hex"),
      Buffer.from(encB64, "base64")
    );
  }

  async encryptContent(buf, aesKeyHex) {
    // use WebCrypto AES-CBC instead
    const iv = this.webcrypto.getRandomValues(new Uint8Array(16));
    // import key material
    const keyBytes = new Uint8Array(Buffer.from(aesKeyHex, "hex"));
    const result = await this._aesCbcEncrypt(buf, keyBytes, iv);
    return result;
  }
  async _aesCbcEncrypt(plaintextBuf, keyBytes, iv) {
    const subtle = this.webcrypto.subtle;
    // import the raw key
    const cryptoKey = await subtle.importKey(
      "raw",
      keyBytes,
      { name: "AES-CBC", length: 256 },
      false,
      ["encrypt"]
    );
    const ciphertext = new Uint8Array(
      await subtle.encrypt({ name: "AES-CBC", iv }, cryptoKey, plaintextBuf)
    );
    // return iv ∥ ciphertext
    const out = new Uint8Array(iv.byteLength + ciphertext.byteLength);
    out.set(iv, 0);
    out.set(ciphertext, iv.byteLength);
    return out;
  }

  async decryptContent(encBuf, aesKeyHex) {
    const iv = encBuf.slice(0, 16);
    const ciphertext = encBuf.slice(16);
    const keyBytes = new Uint8Array(Buffer.from(aesKeyHex, "hex"));
    return this._aesCbcDecrypt(ciphertext, keyBytes, iv);
  }

  async _aesCbcDecrypt(ciphertext, keyBytes, iv) {
    const subtle = this.webcrypto.subtle;
    const cryptoKey = await subtle.importKey(
      "raw",
      keyBytes,
      { name: "AES-CBC", length: 256 },
      false,
      ["decrypt"]
    );
    const plaintext = new Uint8Array(
      await subtle.decrypt({ name: "AES-CBC", iv }, cryptoKey, ciphertext)
    );
    return plaintext;
  }

  hashCID(cid) {
    return this.web3.utils.keccak256(cid);
  }

  publicKeyToAddress(publicKeyHex) {
    // strip the 0x and the '04' prefix
    const keyBuffer = Buffer.from(publicKeyHex.slice(4), "hex");
    // keccak256 of the public key
    const hash = this.web3.utils.keccak256(keyBuffer);
    // take the last 20 bytes (40 hex chars) and prefix with 0x
    return "0x" + hash.slice(-40);
  }

  // Helper: turn a JS object into an encrypted base64 blob
  encryptForOracle(obj) {
    const plain = Buffer.from(JSON.stringify(obj), "utf8");
    const pubKeyHex = this.OTP_ORACLE_PUBLIC_KEY;
    const pubKeyBuf = Buffer.from(pubKeyHex.replace(/^0x/, ""), "hex");
    const cipher = ecies.encrypt(pubKeyBuf, plain);
    return cipher.toString("base64");
  }

