const STORAGE_KEY = "blockchainSDK:wallets";

const isBrowser =
  typeof window !== "undefined" && typeof window.localStorage !== "undefined";

const store = {
  get() {
    if (isBrowser) {
      const raw = localStorage.getItem(STORAGE_KEY);
      const result = raw ? JSON.parse(raw) : {};
      console.log("🔍 localStorage GET - Key:", STORAGE_KEY, "Raw:", raw, "Parsed:", Object.keys(result));
      return result;
    } else {
      throw new Error("This SDK is intended for browser use only.");
    }
  },

  set(obj, isSave = true, aadhaarContext = null) {
    if (!isBrowser) {
      throw new Error("This SDK is intended for browser use only.");
    }

    // 1. Save to localStorage
    console.log("🔍 localStorage SET - Key:", STORAGE_KEY, "Data:", Object.keys(obj), "isSave:", isSave);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(obj));

    // 2. Offer download
    if (isSave) {
      // Generate filename based on aadhaar if provided
      let filename = "wallets.json";
      if (aadhaarContext) {
        filename = `${aadhaarContext}.json`;
      }
      
      const blob = new Blob([JSON.stringify(obj, null, 2)], {
        type: "application/json",
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      a.style.display = "none";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }
  },
};

export default store;
